# DK GRD.  Gram - Rødding
with detail = 2 {
    let gr = path("d2.dk.grd");

    with railway = :first :g1000 :pax :removed {
        with link = "line.dk.GRD" {
            track(gr[:gra.yr, :gra.yr + 4.01km]);
            line_label(:left:e, gr[:gra.yr + 4km] << 0.5lt, "GRD");
            track(gr[:gra.yr + 3.99km, :rod]);
        }

        with link = "point.dk.Rødding" {
            statdot(gr[:rod]);
            slabel(:top, gr[:rod] + (0dt, -0.8dt), "Rødding");
        }
    }
}


# DK GTV.  Gesten - Vejen
with detail = 2 {
    let gv = path("d2.dk.gtv");

    with railway = :first :pax :removed {
        with link = "line.dk.GTV" {
            track(gv[:ges.yv, :ges.yv + 3.31km]);
            line_label(:left:w, gv[:ges.yv + 3.3km] << 0.5mt, "GTV");
            track(gv[:ges.yv + 3.29km, :vej.yg]);
        }
    }
}

